1850	  private applyEnvelope(envelope: ActionEnvelope): { accepted: boolean; state: RestaurantState; error?: ActionError } {
1851	    // Idempotency check
1852	    const cached = this.idempotencyCache.get(envelope.idempotencyKey);
1853	    if (cached) return cached;
1854	
1855	    // Staleness
1856	    if (envelope.tick !== this.currentState.episode.tick) {
1857	      const err: ActionError = { code: "stale_tick", message: "action tick does not match the current tick", retryable: true };
1858	      const res = { accepted: false, state: this.state(), error: err };
1859	      this.idempotencyCache.set(envelope.idempotencyKey, res);
1860	      return res;
1861	    }
1862	
1863	    // Episode completion
1864	    if (this.isOver()) {
1865	      const err: ActionError = { code: "episode_complete", message: "the episode has already ended", retryable: false };
1866	      const res = { accepted: false, state: this.state(), error: err };
1867	      this.idempotencyCache.set(envelope.idempotencyKey, res);
1868	      return res;
1869	    }
1870	
1871	    // Tool permission: a worker is bound to its role's tool list; the player
1872	    // intervenes through a separate, fixed set no worker role is ever
1873	    // granted (see PLAYER_TOOLS) — the manager overrules the floor, but only
1874	    // through the same validated boundary, never a direct state mutation.
1875	    if (envelope.actorType === "worker") {
1876	      const bound = this.bindWorkerEnvelope(envelope);
1877	      if (bound) {
1878	        const res = { accepted: false, state: this.state(), error: bound };
1879	        this.idempotencyCache.set(envelope.idempotencyKey, res);
1880	        return res;
1881	      }
1882	      const allowedTools = ROLE_PERMISSIONS[envelope.role] ?? [];
1883	      if (!allowedTools.includes(envelope.tool)) {
1884	        const err: ActionError = { code: "role_not_permitted", message: `${envelope.role} may not use ${envelope.tool}`, retryable: false };
1885	        const res = { accepted: false, state: this.state(), error: err };
1886	        this.idempotencyCache.set(envelope.idempotencyKey, res);
1887	        return res;
1888	      }
1889	    } else if (!PLAYER_TOOLS.includes(envelope.tool)) {
1890	      const err: ActionError = { code: "role_not_permitted", message: `player may not use ${envelope.tool}`, retryable: false };
1891	      const res = { accepted: false, state: this.state(), error: err };
1892	      this.idempotencyCache.set(envelope.idempotencyKey, res);
1893	      return res;
1894	    }
1895	    // Safety checks (e.g. cooking in failed oven)
1896	    if (envelope.tool === "prepare") {
1897	      const oven = this.currentState.equipment.find((e) => e.kind === "oven");
1898	      if (oven?.status === "failed") {
1899	        const orderId = envelope.arguments.orderId as string | undefined;
1900	        const order = this.currentState.orders.find((o) => o.id === orderId);
1901	        if (order?.items.includes("fish")) {
1902	          const err: ActionError = { code: "unsafe_action", message: "cannot prepare hot item in failed oven", retryable: false };
1903	          const res = { accepted: false, state: this.state(), error: err };
1904	          this.idempotencyCache.set(envelope.idempotencyKey, res);
1905	          return res;
1906	        }
1907	      }
1908	    }
1909	
1910	    // send_message delivers to its recipient's inbox on the next tick's
1911	    // observation and on that tick only.
1912	    if (envelope.tool === "send_message") {
1913	      const to = envelope.arguments.to as string | undefined;
1914	      const text = envelope.arguments.text as string | undefined;
1915	      const priority = (envelope.arguments.priority as Priority | undefined) ?? "normal";
1916	      if (typeof to !== "string" || typeof text !== "string" || text.length === 0 || text.length > 256) {
1917	        const err: ActionError = {
1918	          code: "invalid_arguments",
1919	          message: "send_message requires string 'to' and non-empty 'text' up to 256 characters",
1920	          retryable: false,
1921	        };
1922	        const res = { accepted: false, state: this.state(), error: err };
1923	        this.idempotencyCache.set(envelope.idempotencyKey, res);
1924	        return res;
1925	      }
1926	      if (!this.currentState.workers.some((w) => w.id === to)) {
1927	        const err: ActionError = { code: "unknown_entity", message: `unknown worker ${to}`, retryable: false };
1928	        const res = { accepted: false, state: this.state(), error: err };
1929	        this.idempotencyCache.set(envelope.idempotencyKey, res);
1930	        return res;
1931	      }
1932	      const queued = this.pendingInbox.get(to) ?? [];
1933	      queued.push({ from: envelope.actorId, text, priority, sentAtTick: envelope.tick });
1934	      this.pendingInbox.set(to, queued);
1935	      if (envelope.actorType === "player") {
1936	        const recipient = this.currentState.workers.find((w) => w.id === to);
1937	        const name = recipient ? STAFF[recipient.role].name : to;
1938	        this.log("you", "player", `To ${name}: "${text}"`);
1939	      }
1940	    }
1941	
1942	    // coordinate: the player (or the expediter) moves a ticket's priority.
1943	    // A worker's own coordination doesn't reach this branch today — nothing
1944	    // in `progressWorkers()` emits `coordinate` — but the check stays generic
1945	    // so a future expediter completion is handled the same validated way.
1946	    if (envelope.tool === "coordinate") {
1947	      const orderId = envelope.arguments.orderId as string | undefined;
1948	      const priority = envelope.arguments.priority as Priority | undefined;
1949	      if (typeof orderId !== "string" || !orderId || (priority !== "normal" && priority !== "high")) {
1950	        const err: ActionError = {
1951	          code: "invalid_arguments",
1952	          message: "coordinate requires string 'orderId' and priority 'normal' or 'high'",
1953	          retryable: false,
1954	        };
1955	        const res = { accepted: false, state: this.state(), error: err };
1956	        this.idempotencyCache.set(envelope.idempotencyKey, res);
1957	        return res;
1958	      }
1959	      const order = this.currentState.orders.find((o) => o.id === orderId);
1960	      if (!order) {
1961	        const err: ActionError = { code: "unknown_entity", message: `unknown order ${orderId}`, retryable: false };
1962	        const res = { accepted: false, state: this.state(), error: err };
1963	        this.idempotencyCache.set(envelope.idempotencyKey, res);
1964	        return res;
1965	      }
1966	      if (!ACTIVE_ORDER_STATUSES.has(order.status)) {
1967	        const err: ActionError = {
1968	          code: "invalid_state",
1969	          message: `order ${orderId} is ${order.status} and cannot be prioritised`,
