372	   * does not carry. Live, so the shift view can show how close the night is
373	   * to failing instead of only revealing it in the debrief.
374	   */
375	  readonly tally: { readonly walkouts: number; readonly unsafeServed: number };
376	  /** Which night is being worked, for the pre-shift card. */
377	  readonly shift: { id: string; title: string };
378	  /** Present only once the shift has ended. */
379	  readonly debrief?: Debrief;
380	  readonly timeline?: TimelineModel;
381	  readonly score: number;
382	  /** The one in-shift purchase currently on offer: cost, and whether it's bought. */
383	  readonly upgrade: { id: "second_stove"; label: string; cost: number; bought: boolean };
384	  /** Training-shift prompt. Absent on scored nights. */
385	  readonly coach?: CoachPrompt;
386	}
387	
388	export interface CoachPrompt {
389	  readonly step: number;
390	  readonly total: number;
391	  readonly title: string;
392	  readonly detail: string;
393	}
394	
395	const TUTORIAL_STEPS = 3;
396	
397	/**
398	 * The next thing a first-time player should do on the training shift.
399	 * Scored nights return nothing — a coach line on Dinner Rush would pollute
400	 * the decision surface the benchmark is measuring.
401	 */
402	export function tutorialCoach(view: {
403	  readonly shift: { id: string };
404	  readonly sim: SimControl;
405	  readonly workers: readonly { role: string; location: string }[];
406	  readonly orders: readonly { tableId?: string; status: string; allergy?: string; priority: string }[];
407	  readonly decision?: { id: string };
408	  readonly goal: ShiftGoal;
409	  /** Decision ids already answered this shift — so a resolved allergy call is not re-taught. */
410	  readonly decidedIds?: readonly string[];
411	}): CoachPrompt | undefined {
412	  if (view.shift.id !== TUTORIAL_SHIFT_ID) return undefined;
413	  if (!view.sim.started) {
414	    return {
415	      step: 0,
416	      total: TUTORIAL_STEPS,
417	      title: "Training shift",
418	      detail: "Read the target, then open the doors. Space starts and pauses the clock.",
419	    };
420	  }
421	  const hasRushed = view.orders.some((order) => order.priority === "high");
422	  if (!hasRushed) {
423	    const rushOrder =
424	      view.orders.find((order) => order.tableId === "table-1" && order.status !== "served" && order.status !== "cancelled") ??
425	      view.orders.find((order) => order.status !== "served" && order.status !== "cancelled" && !order.allergy && order.tableId?.match(/^table-[1-3]$/)) ??
426	      view.orders.find((order) => order.status !== "served" && order.status !== "cancelled" && !order.allergy);
427	    if (rushOrder) {
428	      const tableNum = (rushOrder.tableId?.match(/\d+/) ?? ["1"])[0];
429	      const tableLabel = rushOrder.tableId ? rushOrder.tableId.replace("table-", "table ") : "table 1";
430	      const isTable1 = rushOrder.tableId === "table-1";
431	      return {
432	        step: 1,
433	        total: TUTORIAL_STEPS,
434	        title: `Rush ${tableLabel}`,
435	        detail: isTable1
436	          ? "optional — click the pasta ticket (or press 1) to cook that table first"
437	          : `optional — click the ticket (or press ${tableNum}) to cook that table first`,
438	      };
439	    }
440	  }
441	  const allergyDecided = view.decidedIds?.includes("allergy_ticket") === true;
442	  if (!allergyDecided && view.decision?.id === "allergy_ticket") {
443	    return {
444	      step: 2,
445	      total: TUTORIAL_STEPS,
446	      title: "allergy call",
447	      detail: "clock is stopped — pick verify or one unchecked plate fails the night",
448	    };
449	  }
450	  const allergy = view.orders.find((order) => order.allergy && order.status !== "served" && order.status !== "cancelled");
451	  if (!allergyDecided && allergy) {
452	    return {
453	      step: 2,
454	      total: TUTORIAL_STEPS,
455	      title: "protect the allergy",
456	      detail: "click the allergy ticket or press v — one unchecked plate fails the night",
457	    };
458	  }
459	  return {
460	    step: 3,
461	    total: TUTORIAL_STEPS,
462	    title: "Hit the number",
463	    detail: `Take $${view.goal.cash} without an unsafe plate. HOLD the door if the queue piles up.`,
464	  };
465	}
