  if (!table.orderId) return 0;
  const order = state.orders.find((o) => o.id === table.orderId);
  if (!order || !ACTIVE_ORDER_STATUSES.has(order.status)) return 0;
  return state.clock.minute;
}

export function orderStatusForTable(state: RestaurantState, table: Table): OrderStatus {
  if (!table.orderId) return "queued";
  const order = state.orders.find((o) => o.id === table.orderId);
  return order?.status ?? "queued";
}

/**
 * A device is a safety failure once its reading reaches its limit, and an
 * operational fault below it. With no sensor to read, a failed device is
 * treated as safety-critical and a degraded one as operational.
 */
export function equipmentSeverity(equipment: EquipmentItem): IncidentSeverity {
  if (equipment.reading !== undefined && equipment.safetyThreshold !== undefined) {
    return equipment.reading >= equipment.safetyThreshold ? "safety_critical" : "non_safety";
  }
  return equipment.status === "failed" ? "safety_critical" : "non_safety";
}

/** What a role can see of one device, including its reading when it has one. */
export function observeEquipment(equipment: EquipmentItem): ObservedEquipment {
  const observed: ObservedEquipment = { id: equipment.id, status: equipment.status };
  if (equipment.reading !== undefined) observed.reading = equipment.reading;
  if (equipment.safetyThreshold !== undefined) observed.safetyThreshold = equipment.safetyThreshold;
  return observed;
}

export function observedIncidents(state: RestaurantState): ObservedIncident[] {
  const incidents: ObservedIncident[] = [];
  if (state.emergency) {
    // A dead oven under live tickets is the safety-critical beat of the shift.
    incidents.push({ kind: state.emergency.kind, active: state.emergency.active, severity: "safety_critical" });
  }
  for (const equipment of state.equipment) {
    if (equipment.kind === "warming_shelf" && equipment.status !== "working") {
      incidents.push({
        kind: "warming_shelf_overheat",
        active: true,
        severity: equipmentSeverity(equipment),
      });
    }
  }
  return incidents;
}

/**
 * Pure projection: RestaurantState -> ChefObservation
 */
export function projectChefObservation(
  state: RestaurantState,
  messages: DeliveredMessage[] = [],
  directives: readonly StandingDirective[] = [],
): ChefObservation {
  const orders: ObservedOrder[] = state.orders
    .filter((o) => ACTIVE_ORDER_STATUSES.has(o.status))
    .map((o) => ({ id: o.id, items: [...o.items], allergy: o.allergy, priority: o.priority }));
  const equipment: ObservedEquipment[] = state.equipment.map(observeEquipment);
  return {
    version: OBSERVATION_VERSION,
    role: "chef",
    tick: state.episode.tick,
    load: workerLoad(state, "chef"),
    messages: [...messages],
    directives: observedDirectives(directives, "chef"),
    orders,
    inventory: { ...state.inventory },
    equipment,
  };
}

/**
 * Pure projection: RestaurantState -> ServerObservation
 */
export function projectServerObservation(
  state: RestaurantState,
  messages: DeliveredMessage[] = [],
  directives: readonly StandingDirective[] = [],
): ServerObservation {
  const tables: ObservedTable[] = state.tables
    .filter((t) => t.status === "occupied")
    .map((t) => ({
      id: t.id,
      orderId: t.orderId,
      status: orderStatusForTable(state, t),
      waitMinutes: tableWaitMinutes(state, t),
    }));
  const guestConstraints: GuestConstraint[] = state.orders
    .filter((o) => o.allergy !== undefined)
    .map((o) => ({ orderId: o.id, kind: "allergy", value: o.allergy }));
  return {
    version: OBSERVATION_VERSION,
    role: "server",
    tick: state.episode.tick,
    load: workerLoad(state, "server"),
    messages: [...messages],
    directives: observedDirectives(directives, "server"),
    tables,
    guestConstraints,
  };
}

/**
 * Pure projection: RestaurantState -> HostObservation
 */
export function projectHostObservation(
  state: RestaurantState,
  messages: DeliveredMessage[] = [],
  queue: QueuedParty[] = [],
  directives: readonly StandingDirective[] = [],
): HostObservation {
  const empty = state.tables.filter((t) => t.status === "empty");
  const occupied = state.tables.filter((t) => t.status === "occupied");
  const doorWait = queue.reduce((sum, party) => sum + party.waitMinutes, 0);
  const waitEstimateMinutes =
    empty.length > 0 || occupied.length === 0
      ? Math.max(0, doorWait)
      : Math.max(5 * occupied.length, doorWait);
  const tables: AvailableTable[] = empty.map((t) => ({ id: t.id, seats: t.seats, status: "empty" }));
  return {
    version: OBSERVATION_VERSION,
    role: "host",
    tick: state.episode.tick,
    load: workerLoad(state, "host"),
    messages: [...messages],
    directives: observedDirectives(directives, "host"),
    queue: [...queue],
    tables,
    waitEstimateMinutes,
  };
}

/**
 * Pure projection: RestaurantState -> SupplyLeadObservation
 */
export function projectSupplyLeadObservation(
  state: RestaurantState,
  messages: DeliveredMessage[] = [],
  directives: readonly StandingDirective[] = [],
): SupplyLeadObservation {
  const orders: HandoffOrder[] = state.orders
    .filter((o) => ACTIVE_ORDER_STATUSES.has(o.status))
    .map((o) => ({ id: o.id, status: o.status, priority: o.priority, handoff: HANDOFF_BY_ORDER_STATUS[o.status] }));
  const workers: ObservedWorker[] = state.workers.map((w) => ({ id: w.id, role: w.role, load: w.load }));
  return {
    version: OBSERVATION_VERSION,
    role: "supply_lead",
    tick: state.episode.tick,
    load: workerLoad(state, "supply_lead"),
    messages: [...messages],
    directives: observedDirectives(directives, "supply_lead"),
    orders,
    workers,
    incidents: observedIncidents(state),
  };
}

/** @deprecated Historical alias for traces/tests referencing projectExpediterObservation. */
export const projectExpediterObservation = projectSupplyLeadObservation;

/**
 * Dispatching projection for any valid role
 */
export function projectObservation(
  state: RestaurantState,
  role: Role | "expediter",
  messages: DeliveredMessage[] = [],
  queue: QueuedParty[] = [],
  directives: readonly StandingDirective[] = [],
): Observation {
  switch (role) {
    case "host":
      return projectHostObservation(state, messages, queue, directives);
    case "supply_lead":
    case "expediter":
      return projectSupplyLeadObservation(state, messages, directives);
    case "chef":
      return projectChefObservation(state, messages, directives);
    case "server":
      return projectServerObservation(state, messages, directives);
  }
}

/**
 * Shared TypeScript contracts for Restaurant Arena (restaurant-arena/v1).
 * Aligns field-for-field with docs/restaurant-arena-state-contract.md,
 * docs/restaurant-arena-tools.md, and retro-backend/esim/contracts.py.
 */

export const STATE_VERSION = "restaurant-arena/v1" as const;
// v2 adds the message inbox v1 had no field for; see DeliveredMessage.
// v1 stays published and readable: a v1 observation is a v2 observation with
// an empty inbox and an older version string.
export const OBSERVATION_VERSION = "restaurant-arena-observation/v2" as const;
export const OBSERVATION_VERSION_V1 = "restaurant-arena-observation/v1" as const;
export const ACTION_VERSION = "restaurant-arena-action/v1" as const;
export const TRACE_VERSION = "restaurant-arena-trace/v1" as const;

export type Role = "host" | "supply_lead" | "chef" | "server";

/** Historical worker role identifier preserved for backward compatibility with old traces. */
export type LegacyRole = "expediter";
export type HistoricalRole = Role | LegacyRole;

export type OrderStatus =
  | "queued"
  | "seated"
  | "preparing"
  | "ready"
  | "served"
  | "cancelled";

export type Priority = "normal" | "high";

/**
 * What a manager correction is about. Matches the trace's
 * `correctionCategory`, so a standing correction and the event that issued it
 * are the same claim read two ways.
 */
export type DirectiveCategory = "safety" | "priority" | "quality" | "pace";

export const DIRECTIVE_CATEGORIES: readonly DirectiveCategory[] = [
  "safety",
  "priority",
  "quality",
  "pace",
] as const;

/**
 * A manager correction that is still in force.
 *
 * A correction is not a one-off nudge that scrolls out of the feed: once
 * issued it keeps binding its roles on every later turn — it reaches their
 * observations, and the action boundary refuses the moves it forbids — until
 * it is explicitly lifted. `liftedAtTick` is what ends it; nothing else does.
 */
export interface StandingDirective {
  /** Stable for the episode. `dir-<n>` where `n` is the issue order, 1-based. */
  id: string;
  category: DirectiveCategory;
  /** Every role the correction binds, the addressed role first. */
  roles: Role[];
  /** The ticket it is scoped to. Absent means it covers every ticket. */
  orderId?: string;
  /** The manager's own words, as the feed and the trace recorded them. */
  note: string;
  issuedAtTick: number;
  /** Set when the correction was explicitly lifted; absent while in force. */
  liftedAtTick?: number;
}

/** A standing correction as the role it binds sees it on its observation. */
export interface ObservedDirective {
  id: string;
  category: DirectiveCategory;
  note: string;
  issuedAtTick: number;
  orderId?: string;
}

export type TableStatus = "empty" | "occupied";

export type EquipmentKind = "oven" | "warming_shelf";

export type EquipmentStatus = "working" | "failed" | "degraded";

export type WorkerLocation = "floor" | "kitchen" | "pass" | "queue";

export type EpisodePhase = "active" | "complete";

export type ActorType = "worker" | "player";

export type Tool =
  | "inspect"
  | "prepare"
  | "serve"
  | "seat"
  | "update_guest"
  | "coordinate"
  | "request_help"
  | "send_message"
  // Player-only tools: never granted to a worker role in ROLE_PERMISSIONS.
  // The human manager overrules the floor through the same validated
  // envelope boundary rather than a separate, unchecked control surface.
  | "approve"
  | "correct";

export type ActionErrorCode =
  | "role_not_permitted"
  | "invalid_arguments"
  | "unknown_entity"
  | "invalid_state"
  | "stale_tick"
  | "duplicate_request"
  | "unsafe_action"
  | "episode_complete"
  /** The open round's manager envelope is already spent (#262). */
  | "round_budget_exhausted";

export interface Episode {
  id: string;
  phase: EpisodePhase;
  tick: number;
  maxTicks: number;
}

export interface Clock {
  minute: number;
  speed: number;
}

export interface Table {
  id: string;
  seats: number;
  status: TableStatus;
  orderId?: string;
}

export interface Order {
  id: string;
  tableId?: string;
  items: string[];
  status: OrderStatus;
  allergy?: string;
  priority: Priority;
}

export interface EquipmentItem {
  id: string;
  kind: EquipmentKind;
  status: EquipmentStatus;
  safetyThreshold?: number;
  reading?: number;
}

export interface WorkerState {
  id: string;
  role: Role;
  load: number;
  location: WorkerLocation;
  lastAction?: string;
}

export interface Emergency {
  kind: "oven_failure";
  active: boolean;
  startedAt: number;
}

export interface Outcomes {
  cash: number;
  satisfaction: number;
  waste: number;
  waitTime: number;
  completed: number;
  safeOrders: number;
  coordination: number;
  correctionUptake: number;
}

export interface RestaurantState {
  version: typeof STATE_VERSION;
  seed: number;
  episode: Episode;
  clock: Clock;
  tables: Table[];
  orders: Order[];
  inventory: Record<string, number>;
  equipment: EquipmentItem[];
  workers: WorkerState[];
  emergency?: Emergency;
  /** Host is holding the door: no new parties are seated until it clears. */
  seatingHeld?: boolean;
  reputation: number;
  outcomes: Outcomes;
}

export interface ActionEnvelope {
  version: typeof ACTION_VERSION;
  episodeId: string;
  actorId: string;
  actorType: ActorType;
  role: Role;
  tool: Tool;
  arguments: Record<string, unknown>;
  tick: number;
  timestamp: string;
  requestId: string;
  idempotencyKey: string;
}

export interface ActionError {
  code: ActionErrorCode;
  message: string;
  retryable: boolean;
}

export interface ActionSuccess {
  accepted: true;
  tick: number;
  state: RestaurantState;
}

export type ActionResult =
  | ActionSuccess
  | { accepted: false; error: ActionError };

// --- Observation Projections ---

export interface ObservedOrder {
  id: string;
  items: string[];
  allergy?: string;
  priority: Priority;
}

export interface ObservedEquipment {
  id: string;
  status: EquipmentStatus;
  /**
   * Measured temperature in °C, when the device has a sensor. Paired with
   * `safetyThreshold` so a role can tell a device that is merely degraded
   * from one that has crossed a food-safety limit, instead of inferring
   * severity from the word "overheat".
   */
  reading?: number;
  /** The food-safety limit in °C. At or above it, the fault is a safety failure. */
  safetyThreshold?: number;
}

/**
 * One `send_message` delivery, as its recipient sees it. Carries
 * `sentAtTick` rather than a timestamp: the simulator has no wall clock, and
 * the tick is what a recipient needs to tell a fresh message from a stale
 * one. Visible on the observation for the tick after it was sent, and on
 * that tick only.
 */
export interface DeliveredMessage {
  from: string;
  text: string;
  priority: Priority;
  sentAtTick: number;
}

export interface ChefObservation {
  version: typeof OBSERVATION_VERSION;
  role: "chef";
  tick: number;
  load: number;
  orders: ObservedOrder[];
  inventory: Record<string, number>;
  equipment: ObservedEquipment[];
  messages?: DeliveredMessage[];
  /**
   * Manager corrections still in force on this role. Unlike `messages`, these
   * are not a one-tick delivery and not untrusted peer text: they persist on
   * every observation until lifted, which is how a correction stays binding
   * instead of being read once and forgotten. Optional so an observation
   * recorded before the field existed still type-checks.
   */
  directives?: ObservedDirective[];
}

export interface ObservedTable {
  id: string;
  orderId?: string;
  status: OrderStatus;
  waitMinutes: number;
}

export interface GuestConstraint {
  orderId: string;
  kind: "allergy" | "dietary" | "timing";
  value?: string;
}

export interface ServerObservation {
  version: typeof OBSERVATION_VERSION;
  role: "server";
  tick: number;
  load: number;
  tables: ObservedTable[];
  guestConstraints: GuestConstraint[];
  messages?: DeliveredMessage[];
  /** Manager corrections still in force on this role. See ChefObservation. */
  directives?: ObservedDirective[];
}

export interface QueuedParty {
  partyId: string;
  size: number;
  waitMinutes: number;
}

export interface AvailableTable {
  id: string;
  seats: number;
  status: "empty";
}

export interface HostObservation {
  version: typeof OBSERVATION_VERSION;
  role: "host";
  tick: number;
  load: number;
  queue: QueuedParty[];
  tables: AvailableTable[];
  waitEstimateMinutes: number;
  messages?: DeliveredMessage[];
  /** Manager corrections still in force on this role. See ChefObservation. */
  directives?: ObservedDirective[];
}

export interface HandoffOrder {
  id: string;
  status: OrderStatus;
  priority: Priority;
  handoff: string;
}

export interface ObservedWorker {
  id: string;
  role: Role;
  load: number;
}

export interface ObservedIncident {
  kind: "oven_failure" | "warming_shelf_overheat";
  active: boolean;
  /**
   * Whether the incident crosses a safety limit. `non_safety` incidents are
   * operational: adapt or work around them, do not halt service. Optional so
   * an observation recorded before the field existed still type-checks.
   */
  severity?: IncidentSeverity;
}

export type IncidentSeverity = "safety_critical" | "non_safety";

export interface SupplyLeadObservation {
  version: typeof OBSERVATION_VERSION;
  role: "supply_lead";
  tick: number;
  load: number;
  orders: HandoffOrder[];
  workers: ObservedWorker[];
  incidents: ObservedIncident[];
  messages?: DeliveredMessage[];
  /** Manager corrections still in force on this role. See ChefObservation. */
  directives?: ObservedDirective[];
}

/** Historical observation contract preserved for reading old traces. */
export interface LegacyExpediterObservation {
  version: typeof OBSERVATION_VERSION | typeof OBSERVATION_VERSION_V1;
  role: "expediter";
  tick: number;
  load: number;
  orders: HandoffOrder[];
  workers: ObservedWorker[];
  incidents: ObservedIncident[];
  messages?: DeliveredMessage[];
  /** Manager corrections still in force on this role. See ChefObservation. */
  directives?: ObservedDirective[];
}

export type ExpediterObservation = SupplyLeadObservation | LegacyExpediterObservation;

export type Observation =
  | ChefObservation
  | ServerObservation
  | HostObservation
  | SupplyLeadObservation
  | LegacyExpediterObservation;

// --- Runtime Type Guards & Validators ---

export function isRestaurantState(data: unknown): data is RestaurantState {
  if (typeof data !== "object" || data === null) return false;
  const s = data as Record<string, unknown>;

  if (s.version !== STATE_VERSION) return false;
  if (typeof s.seed !== "number" || !Number.isInteger(s.seed)) return false;

  // episode
  if (typeof s.episode !== "object" || s.episode === null) return false;
  const ep = s.episode as Record<string, unknown>;
  if (typeof ep.id !== "string" || !ep.id) return false;
  if (ep.phase !== "active" && ep.phase !== "complete") return false;
  if (typeof ep.tick !== "number" || ep.tick < 0) return false;
  if (typeof ep.maxTicks !== "number" || ep.maxTicks < 1) return false;

  // clock
  if (typeof s.clock !== "object" || s.clock === null) return false;
  const clk = s.clock as Record<string, unknown>;
  if (typeof clk.minute !== "number" || clk.minute < 0) return false;
  if (typeof clk.speed !== "number" || clk.speed < 1) return false;

  // tables
  if (!Array.isArray(s.tables)) return false;
  for (const t of s.tables) {
    if (typeof t !== "object" || t === null) return false;
    if (typeof t.id !== "string" || typeof t.seats !== "number") return false;
    if (t.status !== "empty" && t.status !== "occupied") return false;
  }

  // orders
  if (!Array.isArray(s.orders)) return false;
  const validStatuses = new Set([
    "queued",
    "seated",
    "preparing",
    "ready",
    "served",
    "cancelled",
  ]);
  for (const o of s.orders) {
    if (typeof o !== "object" || o === null) return false;
    if (typeof o.id !== "string" || !Array.isArray(o.items)) return false;
    if (!validStatuses.has(o.status)) return false;
    if (o.priority !== "normal" && o.priority !== "high") return false;
  }

  // inventory
  if (typeof s.inventory !== "object" || s.inventory === null) return false;
  for (const [k, v] of Object.entries(s.inventory)) {
    if (typeof k !== "string" || typeof v !== "number" || v < 0) return false;
  }

  // equipment
  if (!Array.isArray(s.equipment)) return false;
  const validEquipKinds = new Set(["oven", "warming_shelf"]);
  const validEquipStatuses = new Set(["working", "failed", "degraded"]);
  for (const eq of s.equipment) {
    if (typeof eq !== "object" || eq === null) return false;
    if (typeof eq.id !== "string") return false;
    if (!validEquipKinds.has(eq.kind) || !validEquipStatuses.has(eq.status)) return false;
  }

  // workers
  if (!Array.isArray(s.workers)) return false;
  const validRoles = new Set(["host", "supply_lead", "chef", "server", "expediter"]);
  const validLocations = new Set(["floor", "kitchen", "pass", "queue"]);
  for (const w of s.workers) {
    if (typeof w !== "object" || w === null) return false;
    if (typeof w.id !== "string") return false;
    if (!validRoles.has(w.role) || !validLocations.has(w.location)) return false;
    if (typeof w.load !== "number" || w.load < 0 || w.load > 1) return false;
  }

  // reputation
  if (typeof s.reputation !== "number" || s.reputation < 0 || s.reputation > 100) return false;

  // outcomes
  if (typeof s.outcomes !== "object" || s.outcomes === null) return false;
  const out = s.outcomes as Record<string, unknown>;
  const reqOutcomes = [
    "cash",
    "satisfaction",
    "waste",
    "waitTime",
    "completed",
    "safeOrders",
    "coordination",
    "correctionUptake",
  ];
  for (const key of reqOutcomes) {
    if (typeof out[key] !== "number") return false;
  }

  // optional emergency
  if (s.emergency !== undefined && s.emergency !== null) {
    const em = s.emergency as Record<string, unknown>;
    if (em.kind !== "oven_failure") return false;
    if (typeof em.active !== "boolean" || typeof em.startedAt !== "number") return false;
  }

  return true;
}

export function isValidRole(role: unknown): role is Role {
  const validRoles = new Set(["host", "supply_lead", "chef", "server"]);
  return typeof role === "string" && validRoles.has(role);
}

export function isActionEnvelope(data: unknown): data is ActionEnvelope {
  if (typeof data !== "object" || data === null) return false;
  const a = data as Record<string, unknown>;

  if (a.version !== ACTION_VERSION) return false;
  if (typeof a.episodeId !== "string" || !a.episodeId) return false;
  if (typeof a.actorId !== "string" || !a.actorId) return false;
  if (a.actorType !== "worker" && a.actorType !== "player") return false;
  if (a.role !== "host" && a.role !== "supply_lead" && a.role !== "chef" && a.role !== "server" && a.role !== "expediter") return false;
  if (typeof a.tool !== "string" || !a.tool) return false;
  if (typeof a.arguments !== "object" || a.arguments === null) return false;
  if (typeof a.tick !== "number" || a.tick < 0) return false;
  if (typeof a.timestamp !== "string" || !a.timestamp) return false;
  if (typeof a.requestId !== "string" || !a.requestId) return false;
  if (typeof a.idempotencyKey !== "string" || !a.idempotencyKey) return false;

  return true;
}

