        actorId: "player",
        requestId: `evt-noop-${this.currentState.episode.id}-${this.roundNumber}`,
        action: { tool: "no_op", arguments: {} },
      });
      this.log("you", "player", "Held the line — no change this round.");
      moved = true;
      break;
    }

    case "sim_speed": {
