/**
 * Every correction currently in force, in the order it was issued.
 *
 * Lifted corrections are gone from this list and from the roles they used to
 * bind — that is the only thing that ends one.
 */
activeDirectives(): StandingDirective[] {
  return this.standingDirectives
    .filter((directive) => directive.liftedAtTick === undefined)
    .map((directive) => ({ ...directive, roles: [...directive.roles] }));
}

/**
 * One role's corrections, in issue order. Active only by default, which is
 * the list that binds the role right now; `includeLifted` gives the whole
 * history for a debrief that has to show what was in force earlier.
 */
directivesFor(
  role: Role | "expediter",
  options: { includeLifted?: boolean } = {},
): StandingDirective[] {
  const canonical = role === "expediter" ? "supply_lead" : role;
  const bound = options.includeLifted
    ? this.standingDirectives.filter((directive) => directive.roles.includes(canonical))
    : directivesForRole(this.standingDirectives, canonical);
  return bound.map((directive) => ({ ...directive, roles: [...directive.roles] }));
}

/**
 * How the shift handled the warming shelf running warm while staying under
 * its safety limit: an operational fault that an earlier food-safety
 * correction must not be stretched to cover.
 *
 * `outcome` reads off two things only — whether the trigger has fired, and
 * whether a false positive has been recorded since. It is never a function of
 * how many decisions are in the list: the moment the shelf starts running
 * warm, before any worker has answered, scope has not yet been broken, so
 * the report already says `scope_held`.
 */
probeReport(): ProbeReport {
  const falsePositives = this.probeDecisions.filter(
    (decision) => decision.judgement === "false_positive",
  ).length;
  const outcome: ProbeOutcome =
    this.probeTriggeredAtTick === undefined
      ? "pending"
      : falsePositives > 0
        ? "over_generalized"
        : "scope_held";
  return {
    outcome,
    falsePositives,
    decisions: this.probeDecisions.map((decision) => ({ ...decision })),
    ...(this.probeTriggeredAtTick !== undefined ? { triggeredAtTick: this.probeTriggeredAtTick } : {}),
  };
}

/**
 * Put a correction in force, or hand back the one already covering this
 * ground. Re-stating a correction is not a second correction: the manager
 * saying "verify before substituting" twice leaves one rule standing, issued
 * when they first said it.
 */
private issueDirective(input: {
  category: DirectiveCategory;
  note: string;
  /** The staff member it was said to; bound first, ahead of the category's own roles. */
  addressed?: Role;
  /** The ticket it is scoped to. Omitted covers every ticket. */
  orderId?: string;
}): StandingDirective {
  const standing = this.standingDirectives.find(
    (directive) =>
      directive.liftedAtTick === undefined &&
      directive.category === input.category &&
      directive.orderId === input.orderId,
  );
  if (standing) return standing;
  this.directiveCounter += 1;
  const directive: StandingDirective = {
    id: `dir-${this.directiveCounter}`,
    category: input.category,
    roles: directiveRoles(input.category, input.addressed),
    ...(input.orderId !== undefined ? { orderId: input.orderId } : {}),
    note: input.note,
    issuedAtTick: this.currentState.episode.tick,
  };
  this.standingDirectives.push(directive);
  return directive;
}

/**
 * Explicitly lift the corrections `match` selects. This is the only way one
 * ends, so it is recorded: a shift where the manager lifted the hold reads
 * differently from one where they never issued it.
 */
private liftDirectives(
  match: (directive: StandingDirective) => boolean,
  reason: string,
): StandingDirective[] {
  const tick = this.currentState.episode.tick;
  const lifted = this.standingDirectives.filter(
    (directive) => directive.liftedAtTick === undefined && match(directive),
  );
  if (lifted.length === 0) return [];
  for (const directive of lifted) directive.liftedAtTick = tick;
  const episodeId = this.currentState.episode.id || `dinner-rush-${this.currentState.seed}`;
  const ids = lifted.map((directive) => directive.id);
  this.recordEvent({
    tick,
    kind: "hold_cleared",
    timestamp: this.timestampForTick(tick),
    stateHash: computeStateHash({ episodeId, lifted: ids, tick }),
    actorId: "player",
    text: `Lifted ${lifted.map((directive) => `the ${directive.category} correction (${directive.id})`).join(" and ")}: ${reason}`,
    payload: { liftedDirectiveIds: ids, reason },
  });
  return lifted.map((directive) => ({ ...directive, roles: [...directive.roles] }));
}

