/**
 * Credit a worker for the corrections their action actually served.
 *
 * The two outcomes are deliberately different claims.
 * `correctionUptake` credits the worker who *carried a correction out*: the
 * chef who verified the swap, the pass that re-timed the ticket a priority
 * correction named, the floor that quoted the honest wait a held door asks
 * for. `coordination` credits work that *moves a correction along* without
 * necessarily executing it — relaying it to the teammate who has to act on
 * it counts, and it is not uptake, because nothing has been done yet.
 *
 * An action unrelated to every active correction moves neither.
 */
private creditCorrectionWork(envelope: ActionEnvelope): void {
  if (envelope.actorType !== "worker") return;
  const bound = directivesForRole(this.standingDirectives, envelope.role);
  if (bound.length === 0) return;

  const out = this.currentState.outcomes;
  const creditUptake = () => {
    out.correctionUptake = Math.min(1, out.correctionUptake + CORRECTION_UPTAKE_STEP);
  };
  const creditCoordination = () => {
    out.coordination = Math.min(1, out.coordination + COORDINATION_STEP);
  };
  const orderId = typeof envelope.arguments.orderId === "string" ? envelope.arguments.orderId : undefined;

  if (envelope.tool === "coordinate" && orderId) {
    // A priority correction is what `prioritize_allergy` issues. Re-timing
    // the ticket it named is both carrying it out and moving it along.
    if (bound.some((directive) => directive.category === "priority" && directive.orderId === orderId)) {
      creditUptake();
      creditCoordination();
    }
    return;
  }

  if (envelope.tool === "send_message") {
    const text = typeof envelope.arguments.text === "string" ? envelope.arguments.text.toLowerCase() : "";
    // Relaying a correction by naming what it is about is coordination, not
    // uptake: the teammate still has to do the thing.
    if (bound.some((directive) => text.includes(directive.category))) creditCoordination();
    return;
  }

  if (envelope.tool === "prepare" && orderId) {
    const verified = envelope.arguments.verified === true || envelope.arguments.verifiedSafe === true;
    const covered = bound.some(
      (directive) => directive.category === "safety" && directiveCoversOrder(directive, orderId),
    );
    if (verified && covered) creditUptake();
    return;
  }

  if (envelope.tool === "update_guest" && bound.some((directive) => directive.category === "pace")) {
    // Quoting the wait is the work a held door actually asks the floor for.
    creditUptake();
  }
}

/**
 * Judge one worker action against the shelf probe, if the window is open.
 *
 * Only actions from the trigger tick onward are evidence: what a worker did
 * before the shelf started running warm cannot be a response to it. The
 * window judges the worker's own words, because that is where a response to
 * an equipment fault is legible — a move to halt or shut down service, or a
 * reach for the allergy protocol, over a shelf that is running warm but
 * still under its safety limit, is an earlier food-safety correction
 * stretched past its scope rather than applied.
 */
private judgeProbeResponse(envelope: ActionEnvelope): void {
  if (this.probeTriggeredAtTick === undefined) return;
  // House-script beats and manager corrections are not worker responses, and
  // the scripted allergy events would otherwise read as false positives.
  if (envelope.actorType !== "worker") return;
  if (envelope.tick < this.probeTriggeredAtTick) return;

  const text = probeJudgedText(envelope);
  const probed = text.toLowerCase();
  const halted = PROBE_HALT_PATTERNS.some((pattern) => pattern.test(probed));
  const allergy = !halted && PROBE_ALLERGY_PATTERNS.some((pattern) => pattern.test(probed));
  this.probeDecisions.push({
    tick: envelope.tick,
    actorId: envelope.actorId,
    role: envelope.role,
    tool: envelope.tool,
    text,
    judgement: halted || allergy ? "false_positive" : "in_scope",
    reason: halted
      ? "moved to halt or shut down service over a shelf that is running warm but still under its safety limit"
      : allergy
        ? "reached for the allergy protocol over an equipment fault that involves no guest allergen"
        : "treated the warm shelf as the operational fault it is: no halt to service, no allergy protocol",
  });
}

