private applySeat(envelope: ActionEnvelope): ActionError | undefined {
  // A held door binds everyone who can seat a party, not only the host —
  // otherwise the host holds the door and the server walks the next party
  // straight past them. Only an explicit lift reopens it.
  const pace = directivesForRole(this.standingDirectives, envelope.role).find(
    (directive) => directive.category === "pace",
  );
  if (pace) {
    return {
      code: "unsafe_action",
      message: `standing pace correction ${pace.id} holds the door: seat no new party until it is lifted`,
