     ```ts
     export function projectObservation(
       state: RestaurantState,
       role: Role | "expediter",
       messages: DeliveredMessage[] = [],
       queue: QueuedParty[] = [],
       directives: readonly StandingDirective[] = [],
     ): Observation {
