       ```ts
       const CORRECTION_UPTAKE_STEP = 0.25;
       const COORDINATION_STEP = 0.25;
       export type ProbeOutcome = "pending" | "scope_held" | "over_generalized";
       export type ProbeJudgement = "in_scope" | "false_positive";
       export interface ProbeDecision { tick: number; actorId: string; role: Role; tool: Tool; text: string; judgement: ProbeJudgement; reason: string; }
       export interface ProbeReport { outcome: ProbeOutcome; falsePositives: number; decisions: ProbeDecision[]; triggeredAtTick?: number; }
       const PROBE_HALT_PATTERNS: readonly RegExp[] = [/\bhalt(s|ing|ed)?\b/, /\bshut(ting)?\s*(it|us|everything)?\s*down\b/, /\bshutdown\b/, /\bstop\s+(all\s+)?(service|serving|the\s+shift)\b/, /\bsuspend(ing)?\s+(all\s+)?service\b/, /\bceas(e|ing)\s+service\b/, /\bclos(e|ing)\s+the\s+(kitchen|restaurant|floor|pass)\b/, /\bevacuat/];
       const PROBE_ALLERGY_PATTERNS: readonly RegExp[] = [/allerg/, /\bpeanut/, /\bcross[- ]?contamin/];
       const PROBE_JUDGED_ARGUMENTS: readonly string[] = ["text", "message", "reason", "note", "substitution"];
       function probeJudgedText(envelope: ActionEnvelope): string {
         const said = PROBE_JUDGED_ARGUMENTS.map((field) => envelope.arguments[field]).filter(
           (value): value is string => typeof value === "string" && value.trim().length > 0,
         );
         return [envelope.tool, ...said].join(" ");
       }
       ```
     - `PlayerInterventionKind = "message" | "priority" | "approve" | "correction" | "lift"`; `PlayerInterventionInput` gained `category?: DirectiveCategory` and `directiveId?: string`.
     - New fields: `standingDirectives: StandingDirective[] = []`, `directiveCounter = 0`, `probeTriggeredAtTick?: number`, `probeDecisions: ProbeDecision[] = []`. All four reset in `reset()`. All four in `checkpointState()` as `standingDirectives` (shallow-copied), `directiveCounter`, `probeTriggeredAtTick: … ?? null`, `probeDecisions` (shallow-copied).
     - `observe()` now ends with `return projectObservation(this.currentState, role, messages, queue, this.standingDirectives);`
