       ```ts
       activeDirectives(): StandingDirective[] {
         return this.standingDirectives
           .filter((directive) => directive.liftedAtTick === undefined)
           .map((directive) => ({ ...directive, roles: [...directive.roles] }));
       }
       directivesFor(role: Role | "expediter", options: { includeLifted?: boolean } = {}): StandingDirective[] {
         const canonical = role === "expediter" ? "supply_lead" : role;
         const bound = options.includeLifted
           ? this.standingDirectives.filter((directive) => directive.roles.includes(canonical))
