         return bound.map((directive) => ({ ...directive, roles: [...directive.roles] }));
       }
       probeReport(): ProbeReport {
         const falsePositives = this.probeDecisions.filter((d) => d.judgement === "false_positive").length;
         const outcome: ProbeOutcome =
           this.probeTriggeredAtTick === undefined ? "pending" : falsePositives > 0 ? "over_generalized" : "scope_held";
         return { outcome, falsePositives, decisions: this.probeDecisions.map((d) => ({ ...d })),
           ...(this.probeTriggeredAtTick !== undefined ? { triggeredAtTick: this.probeTriggeredAtTick } : {}) };
