/**
 * Compact Decision-and-Correction Timeline Viewer for Restaurant Arena.
 *
 * Presents the 4 key sequence milestones in order:
 *  1. Original decision (Incident trigger & Proposed worker action)
 *  2. Correction (Player intervention & Worker reaction)
 *  3. Later probe (a later, unrelated equipment event)
 *  4. Outcome (Shift outcome metrics)
 */

import type { RestaurantGame } from "./restaurant-game.js";
import type { RestaurantArenaTraceV3, TraceV3Event, TraceV3Role } from "./trace.js";
import type { ArenaView } from "./arena-view.js";
import type { Role } from "./types.js";

export type SequenceMilestone =
  | "original_decision"
  | "correction"
  | "later_probe"
  | "outcome";

export const KEY_SEQUENCE_MILESTONES: readonly SequenceMilestone[] = [
  "original_decision",
  "correction",
  "later_probe",
  "outcome",
] as const;

export type TimelineBadgeTone =
  | "danger"
  | "warning"
  | "info"
  | "success"
  | "neutral";

export interface TimelineCard {
  readonly id: string;
  readonly milestone: SequenceMilestone;
  readonly stepIndex: number; // Recorded order, starting at 1
  readonly title: string;
  readonly role?: Role | TraceV3Role | "player" | "system" | "house";
  readonly tick: number;
  readonly badgeText: string;
  readonly badgeTone: TimelineBadgeTone;
  readonly headline: string;
  readonly detail: string;
  readonly metadata?: Record<string, string | number | boolean>;
}

export interface TimelineModel {
  readonly cards: readonly TimelineCard[];
  readonly milestonesPresented: readonly SequenceMilestone[];
  readonly episodeId: string;
  readonly isComplete: boolean;
}

function escapeHtml(text: string): string {
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

/**
 * What the probe card is careful *not* to claim. The trigger firing is the
 * fault happening, nothing more — reading it as a verdict would credit or
 * blame the floor for a response nobody has made yet.
 */
const PROBE_CARD_DETAIL =
  "A later, unrelated equipment fault, still inside its safety limit. This alone does not establish a worker response: how the floor answered it is in the actions that follow.";

function isTrace(obj: unknown): obj is RestaurantArenaTraceV3 {
  return (
    typeof obj === "object" &&
    obj !== null &&
    (obj as RestaurantArenaTraceV3).version === "restaurant-arena-trace/v3" &&
    Array.isArray((obj as RestaurantArenaTraceV3).events)
  );
}

function isGame(obj: unknown): obj is RestaurantGame {
  return (
    typeof obj === "object" &&
    obj !== null &&
    typeof (obj as RestaurantGame).state === "function" &&
    typeof (obj as RestaurantGame).view === "function"
  );
}

export function buildArenaTimeline(source: RestaurantGame | RestaurantArenaTraceV3 | ArenaView): TimelineModel {
  const trace = isTrace(source);
  const game = isGame(source);
  const state = game ? source.state() : trace ? undefined : source;
  const events: Pick<TraceV3Event, "tick" | "kind" | "actorId" | "role" | "text" | "payload" | "toolResult" | "action" | "probeEventId">[] = trace
    ? source.events
    : game
      ? source.getRecordedEvents()
      : source.feed.map((entry) => ({
          tick: entry.tick,
          kind: entry.voice === "you" ? "player_correction" : entry.kind === "action" ? "action" : "message",
          actorId: entry.voice === "you" ? "player" : entry.voice === "house" ? "system" : entry.voice,
          text: entry.text,
        }));
  const cards: TimelineCard[] = events.map((event, index) => {
    const player = event.actorId === "player" || event.kind === "player_correction";
    const correction = event.kind === "player_correction";
    // The later probe is the trigger event itself, not a reading of it. Naming
    // the milestone here says only that the fault happened; whether anyone
    // over-generalised the earlier correction onto it is a separate question,
    // answered by the worker actions that follow.
    const probe = !!event.probeEventId;
    const milestone: SequenceMilestone = event.kind === "outcome"
      ? "outcome"
      : correction
        ? "correction"
        : probe
          ? "later_probe"
          : "original_decision";
    const failed = event.toolResult?.ok === false;
    return {
      id: `recorded-${index}`, milestone, stepIndex: index + 1,
      title: event.kind === "outcome"
        ? "Shift Outcome Metrics"
        : correction
          ? "Player Intervention"
          : probe
            ? "Later Probe: Unrelated Equipment Fault"
            : "Recorded Event",
      role: player ? "player" : event.role ?? "system",
      tick: event.tick,
      badgeText: failed ? "REJECTED" : probe ? "LATER PROBE" : event.kind.replaceAll("_", " ").toUpperCase(),
      badgeTone: failed ? "danger" : probe ? "warning" : player ? "info" : "neutral",
      headline: event.text ?? `${event.actorId ?? "system"}: ${event.action?.tool ?? event.kind}`,
      detail: event.toolResult?.error?.message ?? (probe ? PROBE_CARD_DETAIL : ""),
    };
  });
  return {
    cards,
    milestonesPresented: KEY_SEQUENCE_MILESTONES.filter((milestone) => cards.some((card) => card.milestone === milestone)),
    episodeId: trace ? source.episodeId : state!.episode.id,
    isComplete: trace ? source.terminal.status === "completed" : state!.episode.phase === "complete",
  };
}

/**
 * Render the Timeline Viewer HTML.
 * Includes milestone progress strip and scrollable chronological cards.
 * Designed to handle large traces gracefully with smooth scrolling and zero visual clipping.
 */
export function renderTimelineHtml(timeline: TimelineModel): string {
  const milestoneLabels: Record<SequenceMilestone, string> = {
    original_decision: "1. Original Decision",
    correction: "2. Player Correction",
    later_probe: "3. Later Probe",
    outcome: "4. Shift Outcomes",
  };

  const stepsHtml = KEY_SEQUENCE_MILESTONES.map((milestone, idx) => {
    const isPresented = timeline.milestonesPresented.includes(milestone);
    return `
      <div class="milestone-step${isPresented ? " is-active" : ""}" data-milestone="${milestone}">
        <span class="milestone-dot">${idx + 1}</span>
        <span class="milestone-name">${escapeHtml(milestoneLabels[milestone])}</span>
      </div>
    `;
  }).join('<div class="milestone-connector"></div>');

  const cardsHtml = timeline.cards
    .map((card) => {
      const toneClass = `badge-${card.badgeTone}`;
      return `
        <div class="arena-timeline-card" data-milestone="${card.milestone}" data-step="${card.stepIndex}">
          <div class="card-header">
            <span class="card-step">#${card.stepIndex}</span>
            <span class="card-badge ${toneClass}">${escapeHtml(card.badgeText)}</span>
            <span class="card-title">${escapeHtml(card.title)}</span>
            <span class="card-tick">Tick ${card.tick}</span>
          </div>
          <p class="card-headline">${escapeHtml(card.headline)}</p>
          <p class="card-detail">${escapeHtml(card.detail)}</p>
        </div>
      `;
    })
    .join("");

  return `
    <div class="arena-timeline" role="region" aria-label="Shift decision and correction timeline" data-sequence="original_decision correction later_probe outcome">
      <div class="arena-timeline-header">
        <span class="arena-timeline-title">DECISION &amp; CORRECTION TIMELINE</span>
        <span class="arena-timeline-badge">${timeline.milestonesPresented.length} MILESTONES</span>
      </div>
      <div class="arena-timeline-milestones">
        ${stepsHtml}
      </div>
      <div class="arena-timeline-cards" tabindex="0" role="feed" aria-label="Chronological decision cards">
        ${cardsHtml}
      </div>
    </div>
  `;
}

import {
  OBSERVATION_VERSION,
  type AvailableTable,
  type ChefObservation,
  type DeliveredMessage,
  type DirectiveCategory,
  type EquipmentItem,
  type ExpediterObservation,
  type GuestConstraint,
  type HandoffOrder,
  type HostObservation,
  type IncidentSeverity,
  type Observation,
  type QueuedParty,
  type ObservedDirective,
  type ObservedEquipment,
  type ObservedIncident,
  type ObservedOrder,
  type ObservedTable,
  type ObservedWorker,
  type OrderStatus,
  type RestaurantState,
  type Role,
  type ServerObservation,
  type StandingDirective,
  type SupplyLeadObservation,
  type Table,
  type Tool,
} from "./types.js";

export const ACTIVE_ORDER_STATUSES: ReadonlySet<OrderStatus> = new Set([
  "queued",
  "seated",
  "preparing",
  "ready",
]);

export const HANDOFF_BY_ORDER_STATUS: Record<OrderStatus, "kitchen" | "pass" | "floor"> = {
  queued: "kitchen",
  seated: "kitchen",
  preparing: "kitchen",
  ready: "pass",
  served: "floor",
  cancelled: "floor",
};

export const ROLE_PERMISSIONS: Record<Role | "expediter", readonly Tool[]> = {
  host: ["inspect", "seat", "update_guest", "request_help", "send_message"],
  supply_lead: ["inspect", "coordinate", "request_help", "send_message"],
  chef: ["inspect", "prepare", "request_help", "send_message"],
  server: ["inspect", "serve", "seat", "update_guest", "request_help", "send_message"],
  expediter: ["inspect", "coordinate", "request_help", "send_message"],
};

/**
 * Which roles a correction binds, by what it is about.
 *
 * A correction is addressed to one member of staff but it is rarely only
 * theirs to carry: "verify before substituting" is the chef's to execute and
 * the supply lead's to protect the time for, and "hold the door" binds
 * everyone who can seat a party — otherwise the host holds the door and the
 * server walks the next party past them.
 */
export const DIRECTIVE_ROLES: Readonly<Record<DirectiveCategory, readonly Role[]>> = {
  safety: ["chef", "supply_lead"],
  priority: ["chef", "supply_lead"],
  quality: ["chef", "supply_lead"],
  pace: ["host", "server"],
};

/** The roles a correction of this category binds, `addressed` named first. */
export function directiveRoles(category: DirectiveCategory, addressed?: Role): Role[] {
  const roles = addressed ? [addressed] : [];
  for (const role of DIRECTIVE_ROLES[category]) {
    if (!roles.includes(role)) roles.push(role);
  }
  return roles;
}

/** In force, and binding on `role`. Order is issue order, as given. */
export function directivesForRole(
  directives: readonly StandingDirective[],
  role: Role | "expediter",
): StandingDirective[] {
  const canonical = role === "expediter" ? "supply_lead" : role;
  return directives.filter((d) => d.liftedAtTick === undefined && d.roles.includes(canonical));
}

/**
 * Whether a correction reaches this ticket. An unscoped correction covers
 * every ticket: "verify before substituting" with no order named is a rule
 * about substitutions, not about one plate.
 */
export function directiveCoversOrder(directive: StandingDirective, orderId: string): boolean {
  return directive.orderId === undefined || directive.orderId === orderId;
}

/** What a bound role sees of a correction: the standing text, not the ledger. */
export function observeDirective(directive: StandingDirective): ObservedDirective {
  return {
    id: directive.id,
    category: directive.category,
    note: directive.note,
    issuedAtTick: directive.issuedAtTick,
    ...(directive.orderId !== undefined ? { orderId: directive.orderId } : {}),
  };
}

function observedDirectives(
  directives: readonly StandingDirective[],
  role: Role | "expediter",
): ObservedDirective[] {
  return directivesForRole(directives, role).map(observeDirective);
}

export function workerLoad(state: RestaurantState, role: Role | "expediter"): number {
  const canonical = role === "expediter" ? "supply_lead" : role;
  const worker = state.workers.find((w) => w.role === canonical || (canonical === "supply_lead" && (w.role as string) === "expediter"));
  if (!worker) throw new Error(`no worker occupies role ${role}`);
  return worker.load;
}

export function tableWaitMinutes(state: RestaurantState, table: Table): number {
  if (!table.orderId) return 0;
  const order = state.orders.find((o) => o.id === table.orderId);
  if (!order || !ACTIVE_ORDER_STATUSES.has(order.status)) return 0;
  return state.clock.minute;
}

export function orderStatusForTable(state: RestaurantState, table: Table): OrderStatus {
  if (!table.orderId) return "queued";
  const order = state.orders.find((o) => o.id === table.orderId);
  return order?.status ?? "queued";
}

/**
 * A device is a safety failure once its reading reaches its limit, and an
 * operational fault below it. With no sensor to read, a failed device is
 * treated as safety-critical and a degraded one as operational.
 */
export function equipmentSeverity(equipment: EquipmentItem): IncidentSeverity {
  if (equipment.reading !== undefined && equipment.safetyThreshold !== undefined) {
    return equipment.reading >= equipment.safetyThreshold ? "safety_critical" : "non_safety";
  }
  return equipment.status === "failed" ? "safety_critical" : "non_safety";
}

/** What a role can see of one device, including its reading when it has one. */
export function observeEquipment(equipment: EquipmentItem): ObservedEquipment {
  const observed: ObservedEquipment = { id: equipment.id, status: equipment.status };
  if (equipment.reading !== undefined) observed.reading = equipment.reading;
  if (equipment.safetyThreshold !== undefined) observed.safetyThreshold = equipment.safetyThreshold;
  return observed;
}

export function observedIncidents(state: RestaurantState): ObservedIncident[] {
  const incidents: ObservedIncident[] = [];
  if (state.emergency) {
    // A dead oven under live tickets is the safety-critical beat of the shift.
    incidents.push({ kind: state.emergency.kind, active: state.emergency.active, severity: "safety_critical" });
  }
  for (const equipment of state.equipment) {
    if (equipment.kind === "warming_shelf" && equipment.status !== "working") {
      incidents.push({
        kind: "warming_shelf_overheat",
        active: true,
        severity: equipmentSeverity(equipment),
      });
    }
  }
  return incidents;
}

/**
 * Pure projection: RestaurantState -> ChefObservation
 */
export function projectChefObservation(
  state: RestaurantState,
  messages: DeliveredMessage[] = [],
  directives: readonly StandingDirective[] = [],
): ChefObservation {
  const orders: ObservedOrder[] = state.orders
    .filter((o) => ACTIVE_ORDER_STATUSES.has(o.status))
    .map((o) => ({ id: o.id, items: [...o.items], allergy: o.allergy, priority: o.priority }));
  const equipment: ObservedEquipment[] = state.equipment.map(observeEquipment);
  return {
    version: OBSERVATION_VERSION,
    role: "chef",
    tick: state.episode.tick,
    load: workerLoad(state, "chef"),
    messages: [...messages],
    directives: observedDirectives(directives, "chef"),
    orders,
    inventory: { ...state.inventory },
    equipment,
  };
}

/**
 * Pure projection: RestaurantState -> ServerObservation
 */
export function projectServerObservation(
  state: RestaurantState,
  messages: DeliveredMessage[] = [],
  directives: readonly StandingDirective[] = [],
): ServerObservation {
  const tables: ObservedTable[] = state.tables
    .filter((t) => t.status === "occupied")
    .map((t) => ({
      id: t.id,
      orderId: t.orderId,
      status: orderStatusForTable(state, t),
      waitMinutes: tableWaitMinutes(state, t),
    }));
  const guestConstraints: GuestConstraint[] = state.orders
    .filter((o) => o.allergy !== undefined)
    .map((o) => ({ orderId: o.id, kind: "allergy", value: o.allergy }));
  return {
    version: OBSERVATION_VERSION,
    role: "server",
    tick: state.episode.tick,
    load: workerLoad(state, "server"),
    messages: [...messages],
    directives: observedDirectives(directives, "server"),
    tables,
    guestConstraints,
  };
}

/**
 * Pure projection: RestaurantState -> HostObservation
 */
export function projectHostObservation(
  state: RestaurantState,
  messages: DeliveredMessage[] = [],
  queue: QueuedParty[] = [],
  directives: readonly StandingDirective[] = [],
): HostObservation {
  const empty = state.tables.filter((t) => t.status === "empty");
  const occupied = state.tables.filter((t) => t.status === "occupied");
  const doorWait = queue.reduce((sum, party) => sum + party.waitMinutes, 0);
  const waitEstimateMinutes =
    empty.length > 0 || occupied.length === 0
      ? Math.max(0, doorWait)
      : Math.max(5 * occupied.length, doorWait);
  const tables: AvailableTable[] = empty.map((t) => ({ id: t.id, seats: t.seats, status: "empty" }));
  return {
    version: OBSERVATION_VERSION,
    role: "host",
    tick: state.episode.tick,
    load: workerLoad(state, "host"),
    messages: [...messages],
    directives: observedDirectives(directives, "host"),
    queue: [...queue],
    tables,
    waitEstimateMinutes,
  };
}

/**
 * Pure projection: RestaurantState -> SupplyLeadObservation
 */
export function projectSupplyLeadObservation(
  state: RestaurantState,
  messages: DeliveredMessage[] = [],
  directives: readonly StandingDirective[] = [],
): SupplyLeadObservation {
  const orders: HandoffOrder[] = state.orders
    .filter((o) => ACTIVE_ORDER_STATUSES.has(o.status))
    .map((o) => ({ id: o.id, status: o.status, priority: o.priority, handoff: HANDOFF_BY_ORDER_STATUS[o.status] }));
  const workers: ObservedWorker[] = state.workers.map((w) => ({ id: w.id, role: w.role, load: w.load }));
  return {
    version: OBSERVATION_VERSION,
    role: "supply_lead",
    tick: state.episode.tick,
    load: workerLoad(state, "supply_lead"),
    messages: [...messages],
    directives: observedDirectives(directives, "supply_lead"),
    orders,
    workers,
    incidents: observedIncidents(state),
  };
}

/** @deprecated Historical alias for traces/tests referencing projectExpediterObservation. */
export const projectExpediterObservation = projectSupplyLeadObservation;

/**
 * Dispatching projection for any valid role
 */
export function projectObservation(
  state: RestaurantState,
  role: Role | "expediter",
  messages: DeliveredMessage[] = [],
  queue: QueuedParty[] = [],
  directives: readonly StandingDirective[] = [],
): Observation {
  switch (role) {
    case "host":
      return projectHostObservation(state, messages, queue, directives);
    case "supply_lead":
    case "expediter":
      return projectSupplyLeadObservation(state, messages, directives);
    case "chef":
      return projectChefObservation(state, messages, directives);
    case "server":
      return projectServerObservation(state, messages, directives);
  }
}

