 * chef who verified the swap, the pass that re-timed the ticket a priority
 * correction named, the floor that quoted the honest wait a held door asks
 * for. `coordination` credits work that *moves a correction along* without
 * necessarily executing it — relaying it to the teammate who has to act on
 * it counts, and it is not uptake, because nothing has been done yet.
 *
 * An action unrelated to every active correction moves neither.
 */
private creditCorrectionWork(envelope: ActionEnvelope): void {
  if (envelope.actorType !== "worker") return;
  const bound = directivesForRole(this.standingDirectives, envelope.role);
  if (bound.length === 0) return;

  const out = this.currentState.outcomes;
  const creditUptake = () => {
    out.correctionUptake = Math.min(1, out.correctionUptake + CORRECTION_UPTAKE_STEP);
  };
  const creditCoordination = () => {
    out.coordination = Math.min(1, out.coordination + COORDINATION_STEP);
  };
  const orderId = typeof envelope.arguments.orderId === "string" ? envelope.arguments.orderId : undefined;

  if (envelope.tool === "coordinate" && orderId) {
    // A priority correction is what `prioritize_allergy` issues. Re-timing
    // the ticket it named is both carrying it out and moving it along.
    if (bound.some((directive) => directive.category === "priority" && directive.orderId === orderId)) {
      creditUptake();
      creditCoordination();
    }
    return;
  }

  if (envelope.tool === "send_message") {
    const text = typeof envelope.arguments.text === "string" ? envelope.arguments.text.toLowerCase() : "";
    // Relaying a correction by naming what it is about is coordination, not
    // uptake: the teammate still has to do the thing.
    if (bound.some((directive) => text.includes(directive.category))) creditCoordination();
    return;
  }

  if (envelope.tool === "prepare" && orderId) {
    const verified = envelope.arguments.verified === true || envelope.arguments.verifiedSafe === true;
    const covered = bound.some(
      (directive) => directive.category === "safety" && directiveCoversOrder(directive, orderId),
    );
    if (verified && covered) creditUptake();
    return;
