      idempotencyKey: "dinner-rush-001:req-unauth-01",
    };

    const initial = game.state();
    const result = game.stepEnvelope(serverPreparing);
    expect(result.accepted).toBe(false);
    expect(result.error?.code).toBe("role_not_permitted");
