  private issueDirective(input: {
    category: DirectiveCategory;
    note: string;
    /** The staff member it was said to; bound first, ahead of the category's own roles. */
    addressed?: Role;
    /** The ticket it is scoped to. Omitted covers every ticket. */
    orderId?: string;
  }): StandingDirective {
    const standing = this.standingDirectives.find(
      (directive) =>
        directive.liftedAtTick === undefined &&
        directive.category === input.category &&
        directive.orderId === input.orderId,
    );
    if (standing) return standing;
    this.directiveCounter += 1;
    const directive: StandingDirective = {
      id: `dir-${this.directiveCounter}`,
      category: input.category,
      roles: directiveRoles(input.category, input.addressed),
      ...(input.orderId !== undefined ? { orderId: input.orderId } : {}),
      note: input.note,
      issuedAtTick: this.currentState.episode.tick,
    };
    this.standingDirectives.push(directive);
    return directive;
  }

  /**
   * Explicitly lift the corrections `match` selects. This is the only way one
   * ends, so it is recorded: a shift where the manager lifted the hold reads
   * differently from one where they never issued it.
   */
  private liftDirectives(
    match: (directive: StandingDirective) => boolean,
    reason: string,
  ): StandingDirective[] {
    const tick = this.currentState.episode.tick;
    const lifted = this.standingDirectives.filter(
      (directive) => directive.liftedAtTick === undefined && match(directive),
    );
    if (lifted.length === 0) return [];
    for (const directive of lifted) directive.liftedAtTick = tick;
    const episodeId = this.currentState.episode.id || `dinner-rush-${this.currentState.seed}`;
    const ids = lifted.map((directive) => directive.id);
    this.recordEvent({
      tick,
      kind: "hold_cleared",
      timestamp: this.timestampForTick(tick),
      stateHash: computeStateHash({ episodeId, lifted: ids, tick }),
      actorId: "player",
      text: `Lifted ${lifted.map((directive) => `the ${directive.category} correction (${directive.id})`).join(" and ")}: ${reason}`,
      payload: { liftedDirectiveIds: ids, reason },
    });
    return lifted.map((directive) => ({ ...directive, roles: [...directive.roles] }));
  }

  score(): number {
    const out = this.currentState.outcomes;
    return Math.round(
      out.cash +
      out.safeOrders * 50 +
      out.satisfaction * 100 -
      out.waste * 10
    );
  }

