describe("probeReport() on the warming shelf (#264)", () => {
  /** Ticks to the scheduled shelf fault at tick 15 on Dinner Rush. */
  function tickToShelfFault(game: RestaurantGame): void {
    while (game.state().episode.tick < 15) game.step("tick");
  }

  it("reads pending until the shelf starts running warm", () => {
    const game = new RestaurantGame(218220);
    expect(game.probeReport()).toEqual({ outcome: "pending", falsePositives: 0, decisions: [] });

    // Words about the allergy protocol before the shelf fault cannot be a
    // response to it, so they are not evidence and do not open the window.
    game.stepEnvelope(
      workerAction(
        game,
        "chef",
        "send_message",
        { to: "worker-server", text: "Watch the allergy ticket on table 2.", priority: "high" },
        "req-pre-trigger-allergy",
      ),
    );
    expect(game.probeReport()).toEqual({ outcome: "pending", falsePositives: 0, decisions: [] });
  });

  it("reads scope_held the moment the trigger fires, before anyone has responded", () => {
    const game = new RestaurantGame(218220);
    game.stepEnvelope(
      workerAction(
        game,
        "chef",
        "send_message",
        { to: "worker-server", text: "Halting nothing — allergy ticket first.", priority: "high" },
        "req-pre-trigger-noise",
      ),
    );
    tickToShelfFault(game);

    // The shelf is warm and still under its limit. Nothing has been asked of
    // the floor yet, so the earlier correction has not been over-generalised.
    const report = game.probeReport();
    expect(report.outcome).toBe("scope_held");
    expect(report.decisions).toEqual([]);
    expect(report.falsePositives).toBe(0);
    expect(report.triggeredAtTick).toBe(15);

    const shelf = game.state().equipment.find((item) => item.id === "warming-shelf-1")!;
    expect(shelf.reading).toBeLessThan(shelf.safetyThreshold!);
  });

  it("holds scope when the floor treats the warm shelf as the operational fault it is", () => {
    const game = new RestaurantGame(218220);
    tickToShelfFault(game);

    const inspected = game.stepEnvelope(
      workerAction(game, "chef", "inspect", { targetId: "warming-shelf-1" }, "req-probe-inspect"),
    );
    expect(inspected.accepted).toBe(true);
    const relayed = game.stepEnvelope(
      workerAction(
        game,
        "supply_lead",
        "send_message",
        { to: "worker-chef", text: "Shelf is warm but under its limit — keep the tickets moving, maintenance is on it.", priority: "normal" },
        "req-probe-relay",
      ),
    );
    expect(relayed.accepted).toBe(true);

    const report = game.probeReport();
    expect(report.outcome).toBe("scope_held");
    expect(report.falsePositives).toBe(0);
    expect(report.decisions.map((decision) => [decision.role, decision.tool, decision.judgement])).toEqual([
      ["chef", "inspect", "in_scope"],
      ["supply_lead", "send_message", "in_scope"],
    ]);
    expect(report.decisions.every((decision) => decision.tick === 15)).toBe(true);
  });

  it("counts a move to halt service as a false positive and reads over_generalized", () => {
    const game = new RestaurantGame(218220);
    tickToShelfFault(game);

    game.stepEnvelope(
      workerAction(
        game,
        "chef",
        "send_message",
        { to: "worker-host", text: "Halting service until the shelf is fixed.", priority: "high" },
        "req-probe-halt",
      ),
    );

    const report = game.probeReport();
    expect(report.outcome).toBe("over_generalized");
    expect(report.falsePositives).toBe(1);
    expect(report.decisions).toHaveLength(1);
    expect(report.decisions[0]?.judgement).toBe("false_positive");
    expect(report.decisions[0]?.reason).toContain("halt");
  });

  it("counts a reach for the allergy protocol as a false positive", () => {
    const game = new RestaurantGame(218220);
    tickToShelfFault(game);

    game.stepEnvelope(
      workerAction(
        game,
        "server",
        "send_message",
        { to: "worker-chef", text: "Running the allergy protocol on every plate off that shelf.", priority: "high" },
        "req-probe-allergy",
      ),
    );

    const report = game.probeReport();
    expect(report.outcome).toBe("over_generalized");
    expect(report.falsePositives).toBe(1);
    expect(report.decisions[0]?.reason).toContain("allergy protocol");
  });

  it("judges an over-generalised move even when the boundary refuses it", () => {
    const game = new RestaurantGame(218220);
    tickToShelfFault(game);

    const refused = game.stepEnvelope(
      workerAction(
        game,
        "chef",
        "prepare",
        { orderId: "order-99", note: "Shutting down the pass until the shelf is fixed." },
        "req-probe-refused-halt",
      ),
    );
    expect(refused.accepted).toBe(false);
    expect(refused.error?.code).toBe("unknown_entity");

    // Reaching for a service-wide shutdown is over-generalisation whether or
    // not the action landed.
    const report = game.probeReport();
    expect(report.outcome).toBe("over_generalized");
    expect(report.falsePositives).toBe(1);
  });

  it("does not count the house script or the manager as worker responses", () => {
    const game = new RestaurantGame(218220);
    tickToShelfFault(game);

    // The scripted allergy beats and a manager correction both mention the
    // allergy protocol. Neither is the floor answering the shelf.
    const corrected = game.submitPlayerIntervention({
      kind: "correction",
      targetRole: "chef",
      text: "Allergy ticket still comes first tonight.",
    });
    expect(corrected.accepted).toBe(true);

    const report = game.probeReport();
    expect(report.outcome).toBe("scope_held");
    expect(report.decisions).toEqual([]);
  });

  it("clears on reset", () => {
    const game = new RestaurantGame(218220);
    tickToShelfFault(game);
    game.stepEnvelope(
      workerAction(
        game,
        "chef",
        "send_message",
        { to: "worker-host", text: "Halting service until the shelf is fixed.", priority: "high" },
        "req-probe-halt-reset",
      ),
    );
    expect(game.probeReport().outcome).toBe("over_generalized");

    game.reset();
    expect(game.probeReport()).toEqual({ outcome: "pending", falsePositives: 0, decisions: [] });
    expect(game.activeDirectives()).toEqual([]);
  });
});

