/**
 * Standing corrections and the warming-shelf probe.
 *
 * A correction that only gets logged is not a correction. These tests hold the
 * two halves of that: the ledger (`directivesFor`, `activeDirectives`) says
 * what is in force, and the action boundary refuses the moves a correction
 * forbids for as long as it stands. The probe tests hold the other edge —
 * a shelf running warm but under its limit is an operational fault, and
 * answering it with a food-safety halt is the earlier correction stretched
 * past its scope.
 */

import { describe, expect, it } from "bun:test";
import { RestaurantGame } from "./restaurant-game.js";
import type { ActionEnvelope, Role, Tool } from "./types.js";

function workerAction(
  game: RestaurantGame,
  role: Role,
  tool: Tool,
  args: Record<string, unknown>,
  requestId: string,
): ActionEnvelope {
  const episode = game.state().episode;
  return {
    version: "restaurant-arena-action/v1",
    episodeId: episode.id,
    actorId: `worker-${role}`,
    actorType: "worker",
    role,
    tool,
    arguments: args,
    tick: episode.tick,
    timestamp: "2026-09-09T18:00:00Z",
    requestId,
    idempotencyKey: `${episode.id}:${requestId}`,
  };
}

/** Two ticks hand the manager the next round's envelope. */
function nextRound(game: RestaurantGame): void {
  game.step("tick");
  game.step("tick");
}

const SAFETY_NOTE = "Protect the allergy ticket: verify before substituting.";

describe("standing corrections stay in force (#264)", () => {
  it("lists a role's corrections in issue order and every one in force", () => {
    const game = new RestaurantGame(218220);
    expect(game.activeDirectives()).toEqual([]);

    const issued = game.submitPlayerIntervention({ kind: "correction", targetRole: "chef", text: SAFETY_NOTE });
    expect(issued.accepted).toBe(true);

    // One call, two corrections: the substitution rule covers every ticket,
    // the re-timing is scoped to the ticket that earned it.
    const chef = game.directivesFor("chef");
    expect(chef.map((directive) => [directive.id, directive.category])).toEqual([
      ["dir-1", "safety"],
      ["dir-2", "priority"],
    ]);
    expect(chef[0]?.orderId).toBeUndefined();
    expect(chef[1]?.orderId).toBe("order-2");
    expect(chef.every((directive) => directive.issuedAtTick === 0)).toBe(true);

    // Bound roles only: nothing was said to the door.
    expect(game.directivesFor("host")).toEqual([]);
    expect(game.directivesFor("supply_lead").map((directive) => directive.id)).toEqual(["dir-1", "dir-2"]);
    expect(game.activeDirectives().map((directive) => directive.id)).toEqual(["dir-1", "dir-2"]);

    nextRound(game);
    game.step("hold_seating");

    // activeDirectives() is the whole floor's ledger, still in issue order.
    expect(game.activeDirectives().map((directive) => [directive.id, directive.category])).toEqual([
      ["dir-1", "safety"],
      ["dir-2", "priority"],
      ["dir-3", "pace"],
    ]);
    // A held door binds everyone who can seat a party.
    expect(game.directivesFor("host").map((directive) => directive.id)).toEqual(["dir-3"]);
    expect(game.directivesFor("server").map((directive) => directive.id)).toEqual(["dir-3"]);
  });

  it("keeps targeting its roles on every later turn, and reaches their observations", () => {
    const game = new RestaurantGame(218220);
    game.submitPlayerIntervention({ kind: "correction", targetRole: "chef", text: SAFETY_NOTE });

    for (let i = 0; i < 6; i++) {
      game.step("tick");
      expect(game.directivesFor("chef").map((directive) => directive.id)).toEqual(["dir-1", "dir-2"]);
      // Still stamped with when it was said, not with now.
      expect(game.directivesFor("chef").every((directive) => directive.issuedAtTick === 0)).toBe(true);
    }

    expect(game.state().episode.tick).toBe(6);
    expect(game.observe("chef").directives).toEqual([
      { id: "dir-1", category: "safety", note: SAFETY_NOTE, issuedAtTick: 0 },
      {
        id: "dir-2",
        category: "priority",
        note: "Allergy ticket first. Clean board, clean pans.",
        issuedAtTick: 0,
        orderId: "order-2",
      },
    ]);
    // A correction is not a message that scrolls away after one tick.
    expect(game.observe("chef").messages).toEqual([]);
    expect(game.observe("host").directives).toEqual([]);
  });

  it("ends a correction only on an explicit lift, and records the lift", () => {
    const game = new RestaurantGame(218220);
    game.submitPlayerIntervention({ kind: "correction", targetRole: "chef", text: SAFETY_NOTE });
    nextRound(game);

    const lifted = game.submitPlayerIntervention({
      kind: "lift",
      targetRole: "chef",
      category: "priority",
      text: "Allergy ticket is out — normal order from here.",
    });
    expect(lifted.accepted).toBe(true);

    expect(game.activeDirectives().map((directive) => directive.id)).toEqual(["dir-1"]);
    expect(game.directivesFor("chef").map((directive) => directive.id)).toEqual(["dir-1"]);
    expect(game.observe("chef").directives?.map((directive) => directive.id)).toEqual(["dir-1"]);

    // The ledger keeps it: a lifted correction is history, not a deletion.
    const withLifted = game.directivesFor("chef", { includeLifted: true });
    expect(withLifted.map((directive) => directive.id)).toEqual(["dir-1", "dir-2"]);
    expect(withLifted[0]?.liftedAtTick).toBeUndefined();
    expect(withLifted[1]?.liftedAtTick).toBe(2);

    const cleared = game.getRecordedEvents().filter((event) => event.kind === "hold_cleared");
    expect(cleared).toHaveLength(1);
    expect(cleared[0]?.payload?.liftedDirectiveIds).toEqual(["dir-2"]);
    expect(cleared[0]?.text).toContain("dir-2");
  });

  it("refuses a lift that names no standing correction", () => {
    const game = new RestaurantGame(218220);
    const before = game.state();
    const result = game.submitPlayerIntervention({ kind: "lift", targetRole: "host", category: "pace" });
    expect(result.accepted).toBe(false);
    expect(result.error?.code).toBe("invalid_state");
    expect(result.error?.message).toBe("no standing correction matches that call");
    expect(game.state()).toEqual(before);
  });
});

